import java.util.*;

public class Test {
    private static int countWords(String s) {
        String t = s + "_";
        boolean hasLetter = false;
        int total = 0;
        for (int i = 0; i < t.length(); i++) {
            char c = t.charAt(i);
            if (Character.isLetter(c)) {
                hasLetter = true;
            } else if (c == '_') {
                if (hasLetter) total++;
                hasLetter = false;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        str += "^";
        n++;
        char[] input = new char[256];
        for (int i = 0; i < n; i++) input[i] = str.charAt(i);

        int flag = 0;
        int count = 0;
        StringBuilder inside = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = input[i];
            if (c == '(') {
                flag = 1;
                input[i] = '^';
                continue;
            } else if (c == ')') {
                flag = 0;
                count += countWords(inside.toString());
                input[i] = '^';
                inside.setLength(0);
            }
            if (flag == 1) {
                inside.append(input[i]);
                input[i] = '^';
            }
        }

        int lastCaret = -1;
        for (int i = 0; i < n; i++) {
            if (input[i] == '^') lastCaret = i;
        }

        int max = 0;
        int current = 0;
        if (lastCaret >= 0) {
            for (int i = 0; i <= lastCaret; i++) {
                char c = input[i];
                if (c == '^') {
                    if (current > max) max = current;
                    current = 0;
                } else if (c == '_') {
                    if (current > max) max = current;
                    current = 0;
                } else if (Character.isLetter(c)) {
                    current++;
                }
            }
        }

        System.out.println(max + " " + count);
    }
}
